{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Desvenlafaxine, the highest-transfer analogue, has an absolute oral bioavailability of approximately 80% in patients, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Zeaxanthin, a long-chain polyene carotenoid, shows high oral bioavailability when ingested with fat, supporting that the query's lipophilic polyene scaffold can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Leflunomide, an amide-containing lipophilic drug, has oral bioavailability as high as 80% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Teriflunomide, the active metabolite of leflunomide, has absolute oral bioavailability approaching 100%, reinforcing that amide/aromatic lipophilic drugs can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cortisone, a lipophilic steroid, has oral bioavailability of about 85%, supporting high F for a lipophilic cyclic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Meperidine, despite substantial first-pass metabolism, has oral bioavailability of about 45%, still well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: all transferable experimental evidence points to oral bioavailability above the 20% threshold, with no affirmative low-bioavailability evidence. The main uncertainty is the query's very low aqueous solubility and high lipophilicity, but analogous lipophilic/amide-containing drugs and a polyene carotenoid support high F.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query retinoid itself.",
    "The query's very low aqueous solubility and high logP may limit absorption, but no experimental evidence in the set directly addresses this.",
    "The closest polyene analogue (zeaxanthin) was assessed in a food matrix, not as a pure drug, and its absolute F was not quantified."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C05", "C23", "C01", "C10", "C06", "C18"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "high-oral-bioavailability drugs"
    }
  ],
  "revision_action": "initial"
}

